import sys

def permute(s, path, used, result):
    if len(path) == len(s):
        result.append(''.join(path))
        return
    for i in range(len(s)):
        if used[i]:
            continue
        if i > 0 and s[i] == s[i-1] and not used[i-1]:
            continue
        used[i] = True
        path.append(s[i])
        permute(s, path, used, result)
        path.pop()
        used[i] = False

def main():
    s = sys.stdin.readline().strip()
    if not s:
        return
    s_list = sorted(list(s))
    used = [False] * len(s_list)
    result = []
    permute(s_list, [], used, result)
    for p in result:
        print(p)

if __name__ == "__main__":
    main()
